-- Arbeitsrecht Berufsbildung > Soziale gesellschaftliche Themen > Arbeitsschutz > Gesundheitsmaßnahmen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Betrieb Gesundheitsmaßnahmen wie ergonomische Arbeitsplätze anbieten?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht gemäß Arbeitsschutzgesetz (ArbSchG) und Bildschirmarbeitsverordnung"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Gesundheitsmaßnahmen in einem IT-Betrieb psychische Belastungen wie Stress reduzieren?', 2, '[{"text": "Ja", "correct": true, "because": "Maßnahmen zielen auf physische und psychische Gesundheit"}, {"text": "Nein", "correct": false, "because": "Psychische Gesundheit ist ein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Gesundheitsmaßnahmen in einem IT-Betrieb freiwillig?', 2, '[{"text": "Nein", "correct": true, "because": "ArbSchG verpflichtet Arbeitgeber zu Maßnahmen"}, {"text": "Ja", "correct": false, "because": "Pflicht gemäß Gesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Gesundheitsmaßnahmen die Krankheitsrate senken?', 2, '[{"text": "Ja", "correct": true, "because": "Prävention reduziert Ausfälle"}, {"text": "Nein", "correct": false, "because": "Gesundheitsförderung wirkt präventiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Gesundheitsmaßnahmen in einem IT-Betrieb regelmäßig überprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "ArbSchG fordert regelmäßige Anpassung"}, {"text": "Nein", "correct": false, "because": "Überprüfung ist Pflicht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz verpflichtet einen IT-Betrieb zu Gesundheitsmaßnahmen?', 2, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "ArbSchG regelt Gesundheitsschutz"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "GmbHG", "correct": false, "because": "Regelt GmbH"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel von Gesundheitsmaßnahmen in einem IT-Betrieb?', 3, '[{"text": "Schutz der Mitarbeitergesundheit", "correct": true, "because": "Prävention ist zentral"}, {"text": "Erhöhung der Arbeitszeit", "correct": false, "because": "Kein Ziel"}, {"text": "Reduktion der Produktivität", "correct": false, "because": "Produktivität steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört typischerweise zu Gesundheitsmaßnahmen in einem IT-Betrieb?', 3, '[{"text": "Ergonomische Arbeitsplätze", "correct": true, "because": "Fördert physische Gesundheit"}, {"text": "Längere Arbeitszeiten", "correct": false, "because": "Nicht gesundheitsfördernd"}, {"text": "Weniger Pausen", "correct": false, "because": "Pausen fördern Gesundheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Umsetzung von Gesundheitsmaßnahmen in einem IT-Betrieb verantwortlich?', 2, '[{"text": "Arbeitgeber", "correct": true, "because": "ArbSchG legt Verantwortung beim Arbeitgeber"}, {"text": "Mitarbeiter", "correct": false, "because": "Mitarbeiter sind nicht verantwortlich"}, {"text": "IHK", "correct": false, "because": "IHK überwacht nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich durch Gesundheitsmaßnahmen für einen IT-Betrieb?', 3, '[{"text": "Geringere Krankheitsrate", "correct": true, "because": "Prävention reduziert Ausfälle"}, {"text": "Höhere Arbeitsbelastung", "correct": false, "because": "Kein Vorteil"}, {"text": "Weniger Produktivität", "correct": false, "because": "Produktivität steigt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Gesundheitsmaßnahmen sind in einem IT-Betrieb üblich?', 4, '[{"text": "Ergonomische Arbeitsplätze", "correct": true, "because": "Schützt vor Haltungsschäden"}, {"text": "Augenschutz bei Bildschirmarbeit", "correct": true, "because": "Reduziert Augenbelastung"}, {"text": "Verlängerte Arbeitszeiten", "correct": false, "because": "Nicht gesundheitsfördernd"}, {"text": "Stressmanagement-Programme", "correct": true, "because": "Fördert psychische Gesundheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Gesundheitsmaßnahmen einem IT-Betrieb?', 3, '[{"text": "Geringere Krankheitsrate", "correct": true, "because": "Prävention reduziert Ausfälle"}, {"text": "Erhöhte Mitarbeiterzufriedenheit", "correct": true, "because": "Gesundheit fördert Motivation"}, {"text": "Höhere Arbeitsbelastung", "correct": false, "because": "Kein Vorteil"}, {"text": "Steigerung der Produktivität", "correct": true, "because": "Gesunde Mitarbeiter sind produktiver"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können Gesundheitsmaßnahmen für einen IT-Betrieb haben?', 4, '[{"text": "Kurzfristige Kosten", "correct": true, "because": "Maßnahmen erfordern Investitionen"}, {"text": "Komplexere Verwaltung", "correct": true, "because": "Umsetzung kann Aufwand erhöhen"}, {"text": "Weniger Mitarbeiterzufriedenheit", "correct": false, "because": "Zufriedenheit steigt"}, {"text": "Zeitaufwand für Umsetzung", "correct": true, "because": "Planung braucht Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln Gesundheitsmaßnahmen in einem IT-Betrieb?', 3, '[{"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": true, "because": "Regelt Gesundheitsschutz"}, {"text": "Bildschirmarbeitsverordnung", "correct": true, "because": "Spezifisch für IT-Arbeitsplätze"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}, {"text": "Sozialgesetzbuch (SGB)", "correct": true, "because": "Enthält Arbeitsschutzvorgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Gesundheit werden durch Maßnahmen in einem IT-Betrieb geschützt?', 3, '[{"text": "Physische Gesundheit", "correct": true, "because": "Ergonomie schützt Körper"}, {"text": "Psychische Gesundheit", "correct": true, "because": "Stressmanagement hilft"}, {"text": "Weniger Produktivität", "correct": false, "because": "Kein Gesundheitsaspekt"}, {"text": "Augengesundheit", "correct": true, "because": "Bildschirmarbeit betrifft Augen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Gesundheitsmaßnahmen sind gesetzlich vorgeschrieben für einen IT-Betrieb. b) Gesundheitsmaßnahmen erhöhen kurzfristig die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Gesetzlich und Kosten"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gesundheitsmaßnahmen reduzieren psychische Belastungen in einem IT-Betrieb. b) Gesundheitsmaßnahmen sind freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Psychische Gesundheit ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gesundheitsmaßnahmen fördern die Produktivität in einem IT-Betrieb. b) Gesundheitsmaßnahmen erhöhen die Krankheitsrate.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Produktivität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ergonomische Arbeitsplätze sind eine Gesundheitsmaßnahme in einem IT-Betrieb. b) Der Arbeitgeber ist nicht für Gesundheitsmaßnahmen verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergonomie ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gesundheitsmaßnahmen verbessern das Image eines IT-Betriebs. b) Gesundheitsmaßnahmen sind nur für Hardwarewartung relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Image ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

